package village.vale;
import io.netty.buffer.*;
import io.netty.handler.codec.DecoderException;
import java.io.*;
import java.util.*;
import org.objectweb.asm.*;
/** Actual direction, input lifecycle, strict wire and scoped native renderer checks. */
public final class DodgeChecks {
    private static int checks;private static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}private static void near(double a,double b,String why){check(Math.abs(a-b)<1e-6,why);}
    public static void main(String[] args)throws Exception{
        check(DodgeMath.direction(1,0)==0&&DodgeMath.direction(-1,0)==1&&DodgeMath.direction(0,1)==2&&DodgeMath.direction(0,-1)==3,"W/S/A/D map to real four directions");check(DodgeMath.direction(0,0)==1&&DodgeMath.direction(Float.NaN,0)==1,"Neutral/invalid input is safe backward");
        double[][] expected={{0,1},{0,-.9},{1,0},{-1,0}};for(int direction=0;direction<4;direction++){double[] v=DodgeMath.velocity(direction,0);near(v[0],expected[direction][0]*DodgeMath.SPEED,"Yaw0 horizontal sign");near(v[2],expected[direction][1]*DodgeMath.SPEED,"Yaw0 depth sign");for(float yaw:new float[]{0,45,90,180,270,-90}){double[] a=DodgeMath.velocity(direction,yaw),rot=DodgeMath.velocity(direction,yaw+360);near(Math.hypot(a[0],a[2]),DodgeMath.SPEED*(direction==1?.9:1),"Direction speed invariant");near(a[0],rot[0],"Yaw wrap X");near(a[2],rot[2],"Yaw wrap Z");}}
        check(!DodgeMath.allowed(true,false,10,11,true,false)&&DodgeMath.allowed(true,false,11,11,true,false),"Exact cooldown boundary");check(!DodgeMath.allowed(false,false,20,0,true,false)&&!DodgeMath.allowed(true,true,20,0,true,false),"Dead/spectator refusal");check(DodgeMath.allowed(true,false,20,0,false,false)&&!DodgeMath.allowed(true,false,20,0,false,true)&&DodgeMath.allowed(true,false,20,0,true,true),"One air use then real landing");check(!DodgeMath.allowed(true,false,-1,0,true,false)&&!DodgeMath.allowed(true,false,20,-1,true,false),"Clock/state corruption refusal");check(DodgeMath.supports("0.3.14")&&DodgeMath.supports("0.3.14-everything")&&!DodgeMath.supports("0.3.13")&&!DodgeMath.supports("0.4.0"),"Protocol floor protects older channels");
        double last=-1;for(int i=0;i<=18;i++){double age=i*.5,p=DodgeMath.progress(age);check(p>=last&&p>=0&&p<=1,"Monotone bounded recovery");last=p;double[] left=DodgeMath.lean(2,age),right=DodgeMath.lean(3,age);near(left[0],right[0],"Side pitch symmetry");near(left[1],-right[1],"Side lean mirror");for(int ghost=0;ghost<3;ghost++)check(DodgeMath.ghostAlpha(ghost,age)>=0&&DodgeMath.ghostAlpha(ghost,age)<=.34,"Bounded ghost alpha");}near(DodgeMath.tuck(0),0,"Start pose releases");near(DodgeMath.tuck(9),0,"End pose releases");near(DodgeMath.ghostAlpha(0,9),0,"Ghosts end without replay");
        net.minecraft.world.border.WorldBorder nativeBorder=new net.minecraft.world.border.WorldBorder();nativeBorder.setCenter(0,0);nativeBorder.setTransition(2);net.minecraft.util.math.AxisAlignedBB crossing=new net.minecraft.util.math.AxisAlignedBB(.8,0,-.2,2.2,2,.2);check(nativeBorder.contains(crossing),"Native border API is only overlap");check(!DodgeMath.insideBorder(crossing.minX,crossing.maxX,crossing.minZ,crossing.maxZ,nativeBorder.minX(),nativeBorder.maxX(),nativeBorder.minZ(),nativeBorder.maxZ()),"Complete swept-box crossing refused");check(DodgeMath.insideBorder(-.8,.8,-.8,.8,-1,1,-1,1),"Real complete containment accepted");check(!DodgeMath.insideBorder(-1,.8,-.8,.8,-1,1,-1,1),"Boundary margin enforced");check(!DodgeMath.insideBorder(Double.NaN,.8,-.8,.8,-1,1,-1,1),"Nonfinite border rejected");check(!DodgeMath.insideBorder(-.8,1.2,-.8,.8,-1,1,-1,1),"MaxX crossing refused");check(!DodgeMath.insideBorder(-1.2,.8,-.8,.8,-1,1,-1,1),"MinX crossing refused");check(!DodgeMath.insideBorder(-.8,.8,-.8,1.2,-1,1,-1,1),"MaxZ crossing refused");check(!DodgeMath.insideBorder(-.8,.8,-1.2,.8,-1,1,-1,1),"MinZ crossing refused");check(!DodgeMath.insideBorder(.8,-.8,-.8,.8,-1,1,-1,1),"Inverted box refused");
        DodgeInput input=new DodgeInput();input.reset(false);check(input.press(true,true,true,false),"Fresh physical press");check(!input.press(true,true,true,false),"Held repeat not another request");input.press(false,true,true,false);check(!input.press(true,true,true,false),"GUI close cannot replay held press");input.press(true,false,false,false);check(input.press(true,true,true,false),"Release rearms after GUI");input.reset(false);check(!input.press(true,true,true,true)&&!input.press(true,true,true,false),"Conflicting legacy action wins this press");input.press(true,false,false,false);check(input.press(true,true,true,false),"Resolved binding works after release");input.reset(true);check(!input.press(true,true,true,false),"Rebind while held cannot activate");input.press(true,false,false,false);check(!input.press(true,true,false,false),"No queued event cannot synthesize press");
        DodgeTrail trail=new DodgeTrail();for(int i=0;i<20;i++)trail.sample(i*.2,80,0,0);check(trail.snapshot().size()==6,"Bounded position history");trail.sample(100,80,0,0);check(trail.snapshot().size()==1,"Teleport breaks visual history");trail.sample(Double.NaN,80,0,0);check(trail.snapshot().isEmpty(),"Nonfinite sample clears history");
        for(int direction=0;direction<4;direction++){ByteBuf bytes=Unpooled.buffer();try{new Dodge.Request(direction,-1).toBytes(bytes);check(bytes.readableBytes()==6,"Fixed request wire");Dodge.Request read=new Dodge.Request();read.fromBytes(bytes);ByteBuf round=Unpooled.buffer();try{read.toBytes(round);check(round.readUnsignedByte()==1&&round.readUnsignedByte()==direction&&round.readInt()==-1,"Direction/dimension roundtrip");}finally{round.release();}}finally{bytes.release();}}
        for(int size:new int[]{0,5,7}){ByteBuf bytes=Unpooled.buffer();try{bytes.writeZero(size);rejectedRequest(bytes);}finally{bytes.release();}}ByteBuf invalid=Unpooled.buffer();try{invalid.writeByte(1).writeByte(4).writeInt(0);rejectedRequest(invalid);}finally{invalid.release();}
        ByteBuf anim=Unpooled.buffer();try{anim.writeByte(1).writeInt(3).writeInt(0).writeLong(1).writeLong(2).writeByte(2).writeByte(16).writeLong(1);check(anim.readableBytes()==35,"Bounded animation wire");Dodge.Anim read=new Dodge.Anim();read.fromBytes(anim);check(read.owner().equals(new UUID(1,2))&&read.entity()==3&&read.direction()==2&&read.sequence()==1,"Animation carries real identity and sequence");}finally{anim.release();}
        byte[] original=resource("/net/minecraft/client/renderer/entity/RenderLivingBase.class");DodgeRenderTransformer transformer=new DodgeRenderTransformer();check(transformer.transform("x","other.Renderer",original)==original,"Unrelated renderer untouched");byte[] patched=transformer.transform("x","net.minecraft.client.renderer.entity.RenderLivingBase",original);final int[] hooks={0},stacks={0};new ClassReader(patched).accept(new ClassVisitor(Opcodes.ASM5){@Override public MethodVisitor visitMethod(int a,String n,String d,String s,String[] e){return new MethodVisitor(Opcodes.ASM5){@Override public void visitMethodInsn(int op,String owner,String name,String desc,boolean itf){if(owner.equals("village/vale/client/DodgeClient")&&name.equals("rotate"))hooks[0]++;}};}},0);check(hooks[0]==1,"One hook inside native body matrix");
        final int[] scope={0,-1,-1,-1,-1};new ClassReader(original).accept(new ClassVisitor(Opcodes.ASM5){@Override public MethodVisitor visitMethod(int access,String name,String descriptor,String signature,String[] exceptions){if((access&Opcodes.ACC_BRIDGE)!=0||!name.equals("doRender")||!descriptor.endsWith(";DDDFF)V"))return null;return new MethodVisitor(Opcodes.ASM5){@Override public void visitMethodInsn(int op,String owner,String name,String d,boolean itf){int at=++scope[0];if(owner.equals("net/minecraftforge/fml/common/eventhandler/EventBus")&&name.equals("post")&&scope[1]<0)scope[1]=at;if(owner.equals("net/minecraft/client/renderer/GlStateManager")&&name.equals("pushMatrix")&&scope[2]<0)scope[2]=at;if(name.equals("applyRotations"))scope[3]=at;}@Override public void visitInsn(int opcode){int at=++scope[0];if(opcode==Opcodes.RETURN&&scope[1]>=0&&scope[2]<0)scope[4]=at;}};}},0);check(scope[1]>=0&&scope[1]<scope[4]&&scope[4]<scope[2]&&scope[2]<scope[3],"Native cancellation return precedes body matrix and our hook");
        System.out.println("PASS: "+checks+" dodge direction/input/wire/trail/scoped-render assertions.");
    }
    private static void rejectedRequest(ByteBuf bytes){boolean failed=false;try{new Dodge.Request().fromBytes(bytes);}catch(DecoderException expected){failed=true;}check(failed,"Malformed request refused before scheduling");}
    private static byte[] resource(String path)throws IOException{try(InputStream stream=DodgeChecks.class.getResourceAsStream(path)){if(stream==null)throw new AssertionError("Missing prepared renderer");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[4096];for(int n;(n=stream.read(buffer))>=0;)out.write(buffer,0,n);return out.toByteArray();}}
}
